// Auto-generated watermark asset for the invoice PDF.
// jsPDF does not perform Unicode text shaping (no ligature/conjunct
// reordering), so Devanagari drawn as live text would render the
// characters of 'कार्य' out of order. To keep the watermark correct
// and crisp, it is pre-rendered once (via a shaping-aware renderer)
// into this small transparent PNG and placed as an image instead.
export const KAARYA_WATERMARK_PNG = 'data:image/png;base64,';
export const KAARYA_WATERMARK_ASPECT = 900 / 590; // width / height
